                "      GradleSyncExtension.EP_NAME.forEachExtensionSafeOrdered { extension ->",
                "        extension.updateBridgeModel(context, phase)",
                "      }",
                "      SYNC_LISTENER.onSyncPhaseCompleted(context, phase)",
                "    }",
